import React from "react";
import { logout } from "../utils/auth";
import NotificationCenter from "./NotificationCenter";

function Navbar() {
  return (
    <nav
      className="navbar navbar-expand-lg navbar-dark sticky-top shadow-sm"
      style={{ backgroundColor: "#02022bf5", zIndex: 1030 }}
    >
      <div className="container-fluid px-4">

        {/* Brand */}
        <a href="/" className="navbar-brand d-flex align-items-center gap-2 fw-bold fs-5">
          <span
            className="d-flex align-items-center justify-content-center rounded-2 bg-white"
            style={{ width: "32px", height: "32px" }}
          >
            <i className="bi bi-bank2 text-primary" style={{ fontSize: "16px" }}></i>
          </span>
          <span>
            Fin<span className="text-warning">Genie</span>
            <span className="fw-light ms-1 text-white-50" style={{ fontSize: "13px" }}>Bank</span>
          </span>
        </a>

        {/* Right side */}
        <div className="d-flex align-items-center gap-3 ms-auto">
          <NotificationCenter />
          <button
            className="btn btn-danger btn-sm fw-semibold rounded-3 px-3"
            onClick={logout}
          >
            <i className="bi bi-box-arrow-right me-1"></i>
            Logout
          </button>
        </div>

      </div>
    </nav>
  );
}

export default Navbar;
